import os
import uuid
import json
import time
import logging
import datetime as dt

import bcrypt
import jwt
import redis
from flask import Flask, request, jsonify, Response

ISSUER = 'rsa-jwt-api'
ACCESS_TTL = dt.timedelta(minutes=15)
REFRESH_TTL = dt.timedelta(days=7)
PRIVATE_KEY_PATH = '/app/keys/private.pem'
PUBLIC_KEY_PATH = '/app/keys/public.pem'
LOG_PATH = '/app/logs/app.log'

os.makedirs('/app/logs', exist_ok=True)
logging.basicConfig(filename=LOG_PATH, level=logging.INFO,
                    format='%(asctime)s %(levelname)s api %(message)s')
log = logging.getLogger('api')

with open(PRIVATE_KEY_PATH) as f:
    PRIVATE_KEY = f.read()
with open(PUBLIC_KEY_PATH) as f:
    PUBLIC_KEY = f.read()

USERS = {'admin': bcrypt.hashpw(b'password123', bcrypt.gensalt())}

REDIS = redis.Redis(host=os.environ.get('REDIS_HOST', 'localhost'),
                    port=int(os.environ.get('REDIS_PORT', '6379')),
                    db=0, decode_responses=True)

app = Flask(__name__)


def now_utc():
    return dt.datetime.now(dt.timezone.utc)


def issue(sub, ttype, ttl):
    t = now_utc()
    claims = {'iss': ISSUER, 'sub': sub, 'iat': t, 'exp': t + ttl,
              'jti': str(uuid.uuid4()), 'type': ttype}
    return jwt.encode(claims, PRIVATE_KEY, algorithm='RS256')


def err(code, msg):
    log.warning('%s %s', code, msg)
    return jsonify(error=msg), code


def decode(token, verify_exp=True):
    return jwt.decode(token, PUBLIC_KEY, algorithms=['RS256'], issuer=ISSUER,
                      options={'verify_exp': verify_exp,
                               'require': ['exp', 'iat', 'jti', 'sub', 'iss']})


def is_revoked(jti):
    return REDIS.exists('blacklist:' + jti) == 1


@app.get('/auth/public-key')
def public_key():
    return Response(PUBLIC_KEY, mimetype='text/plain')


@app.get('/health')
def health():
    return jsonify(status='ok', redis=bool(REDIS.ping()))


@app.post('/auth/login')
def login():
    data = request.get_json(silent=True) or {}
    username = str(data.get('username', ''))
    password = str(data.get('password', ''))
    hashed = USERS.get(username)
    if not hashed or not bcrypt.checkpw(password.encode(), hashed):
        return err(401, 'invalid credentials')
    access = issue(username, 'access', ACCESS_TTL)
    refresh = issue(username, 'refresh', REFRESH_TTL)
    log.info('login ok user=%s', username)
    return jsonify(access_token=access, refresh_token=refresh, token_type='Bearer',
                   access_expires_in=int(ACCESS_TTL.total_seconds()),
                   refresh_expires_in=int(REFRESH_TTL.total_seconds()))


@app.post('/auth/refresh')
def refresh():
    data = request.get_json(silent=True) or {}
    token = data.get('refresh_token', '')
    try:
        claims = decode(token)
    except jwt.ExpiredSignatureError:
        return err(401, 'refresh token expired')
    except jwt.PyJWTError as e:
        return err(401, 'invalid refresh token: %s' % e)
    if claims.get('type') != 'refresh':
        return err(401, 'not a refresh token')
    if is_revoked(claims['jti']):
        return err(403, 'token revoked')
    access = issue(claims['sub'], 'access', ACCESS_TTL)
    return jsonify(access_token=access, token_type='Bearer',
                   access_expires_in=int(ACCESS_TTL.total_seconds()))


@app.post('/auth/revoke')
def revoke():
    data = request.get_json(silent=True) or {}
    token = data.get('token', '')
    try:
        claims = decode(token, verify_exp=False)
    except jwt.PyJWTError as e:
        return err(401, 'invalid token: %s' % e)
    ttl = int(claims['exp'] - time.time())
    if ttl < 1:
        ttl = 1
    REDIS.set('blacklist:' + claims['jti'],
              json.dumps({'sub': claims['sub'], 'type': claims.get('type')}), ex=ttl)
    log.info('revoked jti=%s type=%s ttl=%s', claims['jti'], claims.get('type'), ttl)
    return jsonify(revoked=True, jti=claims['jti'], type=claims.get('type'), ttl=ttl)


@app.get('/auth/validate')
def validate():
    auth = request.headers.get('Authorization', '')
    token = auth[7:] if auth.startswith('Bearer ') else request.args.get('token', '')
    if not token:
        return err(401, 'missing token')
    try:
        claims = decode(token)
    except jwt.ExpiredSignatureError:
        return err(401, 'token expired')
    except jwt.PyJWTError as e:
        return err(401, 'invalid token: %s' % e)
    if is_revoked(claims['jti']):
        return err(403, 'token revoked')
    return jsonify(valid=True, sub=claims['sub'], jti=claims['jti'],
                   type=claims.get('type'), iss=claims['iss'],
                   iat=claims['iat'], exp=claims['exp'])


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', '5000')))
