#!/usr/bin/env python3
import argparse
import json
import logging
import os
import sys
import time

import requests

API = os.environ.get('API_URL', 'http://127.0.0.1:5000')
TOKENS_FILE = '/app/tokens.json'
LOG_PATH = '/app/logs/app.log'
DEFAULT_USER = 'admin'
DEFAULT_PASS = 'password123'

os.makedirs('/app/logs', exist_ok=True)
logging.basicConfig(filename=LOG_PATH, level=logging.INFO,
                    format='%(asctime)s %(levelname)s cli %(message)s')
log = logging.getLogger('cli')


def fail(msg, code=1):
    log.error(msg)
    print('ERROR: ' + msg, file=sys.stderr)
    return code


def load_tokens():
    if not os.path.exists(TOKENS_FILE):
        return None
    with open(TOKENS_FILE) as f:
        return json.load(f)


def save_tokens(data):
    with open(TOKENS_FILE, 'w') as f:
        json.dump(data, f, indent=2)


def http(method, path, **kw):
    kw.setdefault('timeout', 10)
    return requests.request(method, API + path, **kw)


def body_error(resp):
    try:
        return resp.json().get('error', resp.text)
    except ValueError:
        return resp.text


def login(username, password):
    try:
        resp = http('POST', '/auth/login', json={'username': username, 'password': password})
    except requests.RequestException as e:
        return None, 'cannot reach API: %s' % e
    if resp.status_code != 200:
        return None, 'login failed (%d): %s' % (resp.status_code, body_error(resp))
    d = resp.json()
    return {'username': username,
            'access_token': d['access_token'],
            'refresh_token': d['refresh_token'],
            'acquired_at': int(time.time()),
            'revoked': {'access': False, 'refresh': False}}, None


def check(token):
    try:
        resp = http('GET', '/auth/validate', headers={'Authorization': 'Bearer ' + token})
    except requests.RequestException as e:
        return 0, 'cannot reach API: %s' % e
    if resp.status_code == 200:
        return 200, resp.json()
    return resp.status_code, body_error(resp)


def cmd_acquire(a):
    data, err = login(a.username, a.password)
    if err:
        return fail(err)
    save_tokens(data)
    print('Tokens acquired for %s and saved to %s' % (a.username, TOKENS_FILE))
    return 0


def cmd_validate(a):
    data = load_tokens()
    if data is None:
        return fail('no tokens file; run acquire first')
    token = data.get(a.type + '_token')
    if not token:
        return fail('no %s token stored' % a.type)
    status, info = check(token)
    if status == 200:
        print('VALID %s token: %s' % (a.type, json.dumps(info)))
        return 0
    if status == 401 and 'expired' in str(info):
        log.warning('%s token expired', a.type)
        print('EXPIRED: %s token expired. Run: python3 /app/cli.py retry' % a.type)
        return 2
    if status == 403:
        log.warning('%s token revoked', a.type)
        print('REVOKED: %s token has been revoked' % a.type)
        return 3
    return fail('validation failed (%s): %s' % (status, info), 4)


def cmd_revoke(a):
    data = load_tokens()
    if data is None:
        return fail('no tokens file; run acquire first')
    types = ['access', 'refresh'] if a.type == 'all' else [a.type]
    rc = 0
    for t in types:
        token = data.get(t + '_token')
        if not token:
            rc = fail('no %s token stored' % t)
            continue
        try:
            resp = http('POST', '/auth/revoke', json={'token': token})
        except requests.RequestException as e:
            rc = fail('cannot reach API: %s' % e)
            continue
        if resp.status_code != 200:
            rc = fail('revoke %s failed (%d): %s' % (t, resp.status_code, body_error(resp)))
            continue
        data.setdefault('revoked', {})[t] = True
        print('Revoked %s token jti=%s' % (t, resp.json().get('jti')))
    save_tokens(data)
    return rc


def cmd_retry(a):
    data = load_tokens()
    if data is not None and data.get('access_token'):
        status, _ = check(data['access_token'])
        if status == 200:
            print('Access token still valid; nothing to retry')
            return 0
        if data.get('refresh_token') and status == 401:
            try:
                resp = http('POST', '/auth/refresh', json={'refresh_token': data['refresh_token']})
                if resp.status_code == 200:
                    data['access_token'] = resp.json()['access_token']
                    data['acquired_at'] = int(time.time())
                    save_tokens(data)
                    print('Access token refreshed via refresh token')
                    return 0
            except requests.RequestException:
                pass
    username = data.get('username', a.username) if data else a.username
    password = a.password
    last = 'unknown error'
    for attempt in range(1, a.attempts + 1):
        new, err = login(username, password)
        if not err:
            save_tokens(new)
            print('Tokens re-acquired on attempt %d' % attempt)
            return 0
        last = err
        log.warning('retry attempt %d failed: %s', attempt, err)
        print('Attempt %d failed: %s' % (attempt, err), file=sys.stderr)
        if attempt < a.attempts:
            time.sleep(min(2 ** attempt, 10))
    return fail('all %d attempts failed: %s' % (a.attempts, last), 1)


def build_parser():
    p = argparse.ArgumentParser(description='JWT auth CLI')
    sub = p.add_subparsers(dest='command', required=True)

    s = sub.add_parser('acquire', help='login and save tokens')
    s.add_argument('--username', default=DEFAULT_USER)
    s.add_argument('--password', default=DEFAULT_PASS)
    s.set_defaults(func=cmd_acquire)

    s = sub.add_parser('validate', help='validate stored token')
    s.add_argument('--type', choices=['access', 'refresh'], default='access')
    s.set_defaults(func=cmd_validate)

    s = sub.add_parser('revoke', help='revoke stored token(s)')
    s.add_argument('--type', choices=['access', 'refresh', 'all'], default='all')
    s.set_defaults(func=cmd_revoke)

    s = sub.add_parser('retry', help='refresh or re-acquire tokens if expired')
    s.add_argument('--username', default=DEFAULT_USER)
    s.add_argument('--password', default=DEFAULT_PASS)
    s.add_argument('--attempts', type=int, default=3)
    s.set_defaults(func=cmd_retry)
    return p


if __name__ == '__main__':
    args = build_parser().parse_args()
    sys.exit(args.func(args))
